<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,nextTick,watch,reactive,ref} from 'vue';
import ProjectOperations from './ProjectOperations.vue';
import {api} from './api';
import type {OperationsDetail,Role} from './operations';
import {money,bsDate,nepalTime} from './domain'; import {ne} from './i18n';
type Project={role:Role;id:number;name:string;location:string;status:string;budget_paisa:number};
type Material={id:number;name:string;supplier:string;unit:string;quantity_milli:number;rate_paisa:number;total_paisa:number;recorded_on:string};
type Log={id:number;notes:string;recorded_on:string};
type Consultation={id:number;topic:string;mode:string;requested_at:string;status:string};
const lang=ref(localStorage.getItem('ghar-language')||'en');const t=(s:string)=>lang.value==='ne'?(ne[s]||s):s;
function toggleLanguage(){lang.value=lang.value==='en'?'ne':'en';localStorage.setItem('ghar-language',lang.value);document.documentElement.lang=lang.value}
const user=ref<{name:string}|null>(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('');
const projects=ref<Project[]>([]),selected=ref<number|null>(null),tab=ref('Overview'),modal=ref('');
const detail=ref<OperationsDetail & {project:Project;materials:Material[];logs:Log[];consultations:Consultation[];material_total_paisa:number}|null>(null);
const project=computed(()=>projects.value.find(p=>p.id===selected.value));
const budget=computed(()=>projects.value.reduce((s,p)=>s+p.budget_paisa,0));
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kathmandu',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const login=reactive({email:'',password:''});const form=reactive({name:'',location:'',budget:'',supplier:'',quantity:'',rate:'',unit:'bag',client_uuid:'',recorded_on:today,notes:'',topic:'',mode:'video',requested_at:''});
async function loadProjects(){projects.value=await api('/api/projects');if(!selected.value&&projects.value.length)selected.value=projects.value[0].id;if(selected.value)await loadDetail()}
let detailRequest=0;
async function loadDetail(){const id=selected.value,request=++detailRequest;if(detail.value?.project.id!==id)detail.value=null;if(!id)return;const data=await api(`/api/projects/${id}`);if(request===detailRequest&&selected.value===id)detail.value=data}
async function choose(id:number){selected.value=id;tab.value='Materials';await attempt(loadDetail)}
async function attempt(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Something went wrong'}finally{busy.value=false}}
async function signIn(){await attempt(async()=>{await api('/sanctum/csrf-cookie');const d=await api('/login','POST',login);user.value=d.user;login.password='';await loadProjects()})}
async function signOut(){await attempt(async()=>{detailRequest++;await api('/logout','POST');user.value=null;detail.value=null;projects.value=[];selected.value=null;await api('/sanctum/csrf-cookie')})}
function open(kind:string){modal.value=kind;error.value='';form.name='';form.location='';form.budget='';form.supplier='';form.quantity='';form.rate='';form.notes='';form.topic='';form.requested_at='';form.recorded_on=today;form.client_uuid=crypto.randomUUID()}
async function submit(){await attempt(async()=>{const base=`/api/projects/${selected.value}`;
 if(modal.value==='project'){const p=await api('/api/projects','POST',{name:form.name,location:form.location,budget:form.budget});selected.value=p.id;await loadProjects();tab.value='Materials'}
 if(modal.value==='material'){await api(`${base}/materials`,'POST',{name:form.name,supplier:form.supplier,quantity:form.quantity,rate:form.rate,unit:form.unit,recorded_on:form.recorded_on});await loadDetail()}
 if(modal.value==='log'){await api(`${base}/logs`,'POST',{client_uuid:form.client_uuid,recorded_on:form.recorded_on,notes:form.notes});await loadDetail()}
 if(modal.value==='consultation'){await api(`${base}/consultations`,'POST',{topic:form.topic,mode:form.mode,requested_at:form.requested_at+':00+05:45'});await loadDetail()}
 modal.value='';notice.value=t('Save')+' ✓';setTimeout(()=>notice.value='',3000)
})}
onMounted(async()=>{document.documentElement.lang=lang.value;try{await api('/sanctum/csrf-cookie');user.value=await api('/api/me');await loadProjects()}catch(e){if(user.value)error.value=e instanceof Error?e.message:'Request failed'}finally{loading.value=false}});
let previousFocus:HTMLElement|null=null;
watch(modal,async value=>{document.body.style.overflow=value?'hidden':'';if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();(document.querySelector('[role=dialog] input,[role=dialog] textarea,[role=dialog] select') as HTMLElement)?.focus()}else{previousFocus?.focus()}});
function modalKeyboard(event:KeyboardEvent){if(!modal.value)return;if(event.key==='Escape'&&!busy.value){modal.value='';return}if(event.key!=='Tab')return;const controls=Array.from(document.querySelectorAll<HTMLElement>('[role=dialog] button:not(:disabled),[role=dialog] input,[role=dialog] select,[role=dialog] textarea'));const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(()=>document.addEventListener('keydown',modalKeyboard));onBeforeUnmount(()=>document.removeEventListener('keydown',modalKeyboard));
const title=computed(()=>({project:'New project',material:'Add material',log:'Add site log',consultation:'Request consultation'}[modal.value]||''));
</script>
<template>
<div v-if="loading" class="loading" role="status">Ghar Manager · Loading…</div>
<div v-else-if="!user" class="login-screen">
 <section class="login-intro"><a class="brand" href="/" aria-label="Ghar Manager home"><span class="brand-mark">⌂</span><span>Ghar<span class="brand-light">Manager</span></span></a><div class="eyebrow">BUILT FOR YOUR NEXT CHAPTER</div><h1>{{t('Your home, one clear picture.')}}</h1><p>{{t('From the first foundation to the final detail.')}}</p><div class="intro-notes"><span>01 / {{t('Projects')}}</span><span>02 / {{t('Site diary')}}</span><span>03 / {{t('Consultations')}}</span></div></section>
 <section class="login-card glass"><button class="language" @click="toggleLanguage">{{lang==='en'?'नेपाली':'English'}}</button><span class="eyebrow">GHAR MANAGER</span><h2>{{t('Welcome home.')}}</h2><p>{{t('Build with clarity.')}}</p><form @submit.prevent="signIn"><label>{{t('Email')}}<input v-model="login.email" type="email" autocomplete="username" required></label><label>{{t('Password')}}<input v-model="login.password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary full" :disabled="busy">{{busy?'…':t('Sign in')}}</button></form><p class="dev-note">{{t('Development preview')}} · No public registration yet.</p></section>
</div>
<div v-else class="shell">
 <aside class="sidebar glass"><a class="brand" href="/"><span class="brand-mark">⌂</span><span>Ghar<span class="brand-light">Manager</span></span></a><div class="sidebar-caption">BUILD WITH CLARITY</div><nav aria-label="Main navigation"><button v-for="(item,i) in ['Overview','Projects','Materials','Labor','Bills & payments','Site diary','Consultations','Team','Activity']" :key="item" :disabled="busy" :class="{active:tab===item}" @click="tab=item;error=''" :aria-current="tab===item?'page':undefined"><span class="nav-icon" aria-hidden="true">{{['◫','▦','▤','♧','▣','▧','◎','♙','◷'][i]}}</span>{{t(item)}}</button></nav><div class="sidebar-foot"><span class="avatar">{{user.name.charAt(0)}}</span><div><strong>{{user.name}}</strong><small>{{t('Project workspace')}}</small></div></div></aside>
 <div class="main-column"><header class="topbar"><div class="breadcrumb">{{t('Project workspace')}} <span>/</span> {{t(tab)}}</div><div class="top-actions"><button class="language" @click="toggleLanguage">{{lang==='en'?'नेपाली':'English'}}</button><button class="text-button" @click="signOut" :disabled="busy">{{t('Sign out')}}</button></div></header>
 <main><p v-if="error && !modal" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
 <template v-if="tab==='Overview'"><div class="page-heading"><div><div class="eyebrow">{{today}} AD · {{bsDate(today)}} BS</div><h1>{{t('Your home, one clear picture.')}}</h1><p>{{t('From the first foundation to the final detail.')}}</p></div><button class="primary" @click="open('project')">＋ {{t('New project')}}</button></div>
 <div class="stats"><article class="stat glass"><span>{{t('Active projects')}}</span><strong>{{projects.filter(p=>p.status==='active').length.toString().padStart(2,'0')}}</strong><small>{{t('Your projects')}}</small></article><article class="stat glass"><span>{{t('Planned budget')}}</span><strong class="money">{{money(budget)}}</strong><small>NPR · across your projects</small></article><article class="stat glass"><span>{{t('Recorded materials')}}</span><strong class="money">{{money(detail?.material_total_paisa||0)}}</strong><small>{{project?.name||'Select a project'}}</small></article></div>
 <div class="section-heading"><h2>{{t('Your projects')}}</h2><button class="text-button" @click="tab='Projects'">{{t('View all projects')}} ↗</button></div><div class="project-grid"><article v-for="p in projects" :key="p.id" class="project-card glass"><div class="project-top"><span class="project-monogram">⌂</span><span class="badge">{{t(p.status)}}</span></div><h3>{{p.name}}</h3><p class="muted">{{p.location}}</p><div class="project-meta"><span>{{t('Planned budget')}}</span><strong>{{money(p.budget_paisa)}}</strong></div><button :disabled="busy" class="project-open" @click="choose(p.id)">{{t('Open project')}} <span>→</span></button></article><div v-if="!projects.length" class="empty glass">{{t('Create your first project to begin.')}}</div></div>
 <section class="next-panel glass"><div><div class="eyebrow">A LITTLE PROGRESS, EVERY DAY</div><h2>{{t('Your next steps')}}</h2></div><button @click="tab='Materials'"><span>01</span>{{t('Keep every delivery on record.')}} →</button><button @click="tab='Site diary'"><span>02</span>{{t('Capture today’s progress.')}} →</button><button @click="tab='Consultations'"><span>03</span>{{t('Talk to your advisory team.')}} →</button></section></template>
 <template v-else-if="tab==='Projects'"><div class="page-heading"><div><div class="eyebrow">YOUR BUILDING JOURNEY</div><h1>{{t('Your projects')}}</h1><p>{{t('Track the details. Build with confidence.')}}</p></div><button class="primary" @click="open('project')">＋ {{t('New project')}}</button></div><div class="project-grid"><article class="project-card glass" v-for="p in projects" :key="p.id"><span class="badge">{{t(p.status)}}</span><h3>{{p.name}}</h3><p>{{p.location}}</p><div class="project-meta"><span>{{t('Planned budget')}}</span><strong>{{money(p.budget_paisa)}}</strong></div><button :disabled="busy" class="project-open" @click="choose(p.id)">{{t('Open project')}} →</button></article></div><p v-if="!projects.length">{{t('No projects yet.')}}</p></template>
 <template v-else><div class="page-heading"><div><div class="eyebrow">{{project?.location||'YOUR PROJECT'}}</div><h1>{{t(tab)}}</h1><p>{{t('Track the details. Build with confidence.')}}</p></div><label class="project-select">{{t('Projects')}}<select v-model="selected" :disabled="busy" @change="attempt(loadDetail)"><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div>
 <div v-if="!project" class="empty glass">{{t('Create your first project to begin.')}}<button class="primary" @click="open('project')">{{t('New project')}}</button></div>
 <p v-else-if="!detail" role="status">{{t('Loading…')}}</p>
 <ProjectOperations v-else-if="['Labor','Bills & payments','Team','Activity'].includes(tab)" :detail="detail" :tab="tab" :t="t" :refresh="loadDetail" @busy="busy=$event" />
 <template v-else-if="tab==='Materials'"><section class="panel glass"><div class="section-heading"><div><h2>{{t('Material register')}}</h2><p class="muted">{{t('Recorded cost')}}: <strong>{{money(detail?.material_total_paisa||0)}}</strong></p></div><button v-if="detail?.permissions.write_site" class="primary" :disabled="busy" @click="open('material')">＋ {{t('Add material')}}</button></div><div class="table-wrap"><table><thead><tr><th>{{t('Material')}}</th><th>{{t('Supplier')}}</th><th>{{t('Quantity')}}</th><th>{{t('Date')}}</th><th>{{t('Amount')}}</th></tr></thead><tbody><tr v-for="m in detail?.materials" :key="m.id"><td><strong>{{m.name}}</strong><small>{{money(m.rate_paisa)}} / {{m.unit}}</small></td><td :data-label="t('Supplier')">{{m.supplier}}</td><td :data-label="t('Quantity')">{{m.quantity_milli/1000}} {{m.unit}}</td><td :data-label="t('Date')">{{bsDate(m.recorded_on)}} BS<small>{{m.recorded_on}} AD</small></td><td class="amount" :data-label="t('Amount')">{{money(m.total_paisa)}}</td></tr></tbody></table></div><div v-if="!detail?.materials.length" class="empty">{{t('No materials recorded yet.')}}</div></section></template>
 <template v-else-if="tab==='Site diary'"><section class="panel glass"><div class="section-heading"><h2>{{t('Daily site log')}}</h2><button v-if="detail?.permissions.write_site" class="primary" :disabled="busy" @click="open('log')">＋ {{t('Add site log')}}</button></div><article v-for="log in detail?.logs" :key="log.id" class="log-entry"><span class="eyebrow">{{bsDate(log.recorded_on)}} BS · {{log.recorded_on}} AD</span><p class="log-notes">{{log.notes}}</p></article><div v-if="!detail?.logs.length" class="empty">{{t('No site logs yet.')}}</div></section></template>
 <template v-else-if="tab==='Consultations'"><section class="panel glass"><div class="section-heading"><h2>{{t('Consultation requests')}}</h2><button v-if="detail?.permissions.write_site" class="primary" :disabled="busy" @click="open('consultation')">＋ {{t('Request consultation')}}</button></div><p class="muted">{{t('Request only — confirmation is pending.')}}</p><article v-for="c in detail?.consultations" :key="c.id" class="consult-entry"><div><h3>{{c.topic}}</h3><p>{{nepalTime(c.requested_at)}} NPT · {{c.mode}}</p></div><span class="badge">{{t(c.status)}}</span></article><div v-if="!detail?.consultations.length" class="empty">{{t('No consultations requested yet.')}}</div></section></template></template>
 <footer>Ghar Manager <span>·</span> {{t('Build with clarity.')}} <span class="footer-status">{{t('Development preview')}}</span></footer>
 </main></div>
</div>
<div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal='')"><section class="modal glass" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown.esc="!busy&&(modal='')"><div class="section-heading"><h2 id="modal-title">{{t(title)}}</h2><button class="close" aria-label="Close dialog" @click="!busy&&(modal='')">×</button></div><form @submit.prevent="submit">
 <template v-if="modal==='project'"><label>{{t('Project name')}}<input v-model="form.name" required maxlength="120"></label><label>{{t('Location')}}<input v-model="form.location" required maxlength="160"></label><label>{{t('Budget (NPR)')}}<input v-model="form.budget" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required></label></template>
 <template v-if="modal==='material'"><label>{{t('Material')}}<input v-model="form.name" required maxlength="100"></label><label>{{t('Supplier')}}<input v-model="form.supplier" required maxlength="120"></label><div class="form-row"><label>{{t('Quantity')}}<input v-model="form.quantity" inputmode="decimal" required></label><label>{{t('Unit')}}<select v-model="form.unit"><option v-for="u in ['bag','kg','tonne','piece','cft','sqft','m3']" :key="u">{{u}}</option></select></label></div><label>{{t('Rate (NPR)')}}<input v-model="form.rate" inputmode="decimal" required></label></template>
 <label v-if="['material','log'].includes(modal)">{{t('Date (AD)')}}<input v-model="form.recorded_on" type="date" required><small>{{bsDate(form.recorded_on)}} BS</small></label>
 <label v-if="modal==='log'">{{t('What happened on site?')}}<textarea v-model="form.notes" rows="5" maxlength="5000" required></textarea></label>
 <template v-if="modal==='consultation'"><label>{{t('Topic')}}<input v-model="form.topic" required maxlength="160"></label><label>{{t('Meeting type')}}<select v-model="form.mode"><option value="video">{{t('Video')}}</option><option value="in-person">{{t('In person')}}</option></select></label><label>{{t('Preferred time (Nepal)')}}<input v-model="form.requested_at" type="datetime-local" required></label><p class="muted">{{t('Request only — confirmation is pending.')}}</p></template>
 <p v-if="error" class="error" role="alert">{{error}}</p><div class="modal-actions"><button type="button" class="secondary" @click="modal=''" :disabled="busy">{{t('Cancel')}}</button><button class="primary" :disabled="busy">{{busy?'…':t(modal==='project'?'Create project':modal==='consultation'?'Request meeting':'Save')}}</button></div></form></section></div>
</template>
